(function($){'use strict';const Modal={active:null,init:function(){this.bindOpen();this.bindClose();this.bindOverlay();this.bindEscape();},open:function(modal){if(!modal.length){return;}
this.closeAll();this.active=modal;$('body').addClass('nba-modal-open').css('overflow','hidden');modal.attr('aria-hidden','false').fadeIn(200);window.setTimeout(function(){modal.find('input, textarea, select, button').filter(':visible').first().trigger('focus');},210);},close:function(modal){if(!modal.length){return;}
modal.attr('aria-hidden','true').fadeOut(200);$('body').removeClass('nba-modal-open').css('overflow','');this.active=null;},closeAll:function(){const self=this;$('.nba-modal:visible').each(function(){self.close($(this));});},bindOpen:function(){const self=this;$(document).on('click','[data-modal]',function(e){e.preventDefault();const target=$(this).data('modal');if(!target){return;}
self.open($(target));});},bindClose:function(){const self=this;$(document).on('click','.nba-modal-close,[data-modal-close]',function(e){e.preventDefault();self.close($(this).closest('.nba-modal'));});},bindOverlay:function(){const self=this;$(document).on('click','.nba-modal',function(e){if($(e.target).is('.nba-modal')){self.close($(this));}});},bindEscape:function(){const self=this;$(document).on('keydown',function(e){if(e.key==='Escape'){self.closeAll();}});}};$(function(){Modal.init();window.NBAccountsModal=Modal;});})(jQuery);